// =============================================================================
// Identity generation (unit-testable, no side effects)
// =============================================================================
SmokeIdentity generateSmokeIdentity({
  required String emailPrefix,
  required String emailDomain,
}) {
  final now = DateTime.now();
  final datePart =
      '${now.year}${_pad(now.month)}${_pad(now.day)}-${_pad(now.hour)}${_pad(now.minute)}${_pad(now.second)}';
  final randPart = _randomAlphanumeric(8);
  final email = '$emailPrefix-$datePart-$randPart@$emailDomain';
  final displayName = 'SmokeBot-$datePart-$randPart';
  // Fixed password for smoke testing — not a real credential
  const password = 'smoke-test-password-not-real';
  return SmokeIdentity(
    email: email,
    displayName: displayName,
    password: password,
  );
}

String _pad(int n) => n.toString().padLeft(2, '0');

String _randomAlphanumeric(int length) {
  const chars =
      'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  final rand = DateTime.now().microsecondsSinceEpoch;
  final buf = StringBuffer();
  for (var i = 0; i < length; i++) {
    buf.write(chars[(rand + i * 7) % chars.length]);
  }
  return buf.toString();
}

// =============================================================================
// Precheck results
// =============================================================================
class PrecheckResult {
  final String key;
  final bool present;

  const PrecheckResult({required this.key, required this.present});
}

// =============================================================================
// Output formatting
// =============================================================================
void _log(String tag, String message) {
  // Structured log — tag is [TAG] format, message is human-readable.
  // NO secret values are ever printed.
  print('[$tag] $message');
}

void _logResult(String result) {
  print('[RESULT] $result');
}

// =============================================================================
// Precheck logic (dry-run compatible)
// =============================================================================
List<PrecheckResult> runPrechecks(SmokeConfig config, RunMode mode) {
  final results = <PrecheckResult>[];

  // Env presence checks
  results.add(
    PrecheckResult(key: 'SUPABASE_URL', present: config.supabaseUrl.isNotEmpty),
  );
  results.add(
    PrecheckResult(
      key: 'SUPABASE_ANON_KEY',
      present: config.anonKey.isNotEmpty,
    ),
  );
  results.add(
    PrecheckResult(
      key: 'SUPABASE_SERVICE_ROLE_KEY',
      present: config.serviceRoleKey.isNotEmpty,
    ),
  );

  // Log precheck results
  for (final r in results) {
    _log('PRECHECK', '${r.key}: ${r.present ? "present" : "missing"}');
  }

  // Migration 007 / trigger checks are skipped in dry-run
  if (mode == RunMode.execute) {
    _log('PRECHECK', 'migration_007_verification: planned');
    _log('PRECHECK', 'trigger_on_auth_user_insert: planned');
    _log('PRECHECK', 'auth_settings: planned');
  } else {
    _log('PRECHECK', 'migration_007_verification: skipped_in_dry_run');
    _log('PRECHECK', 'trigger_on_auth_user_insert: skipped_in_dry_run');
    _log('PRECHECK', 'auth_settings: skipped_in_dry_run');
  }

  return results;
}

// =============================================================================
// Validation helpers
// =============================================================================
bool allRequiredEnvPresent(List<PrecheckResult> prechecks) {
  // SUPABASE_URL and SUPABASE_ANON_KEY are hard requirements in both modes.
  // SERVICE_ROLE_KEY is required only in execute mode for cleanup.
  return prechecks
      .where((r) => r.key == 'SUPABASE_URL' || r.key == 'SUPABASE_ANON_KEY')
      .every((r) => r.present);
}

bool serviceRolePresent(List<PrecheckResult> prechecks) {
  return prechecks.any(
    (r) => r.key == 'SUPABASE_SERVICE_ROLE_KEY' && r.present,
  );
}

