// =============================================================================
// Dry-run mode
// =============================================================================
Future<int> runDryRun(
  SmokeConfig config,
  SmokeIdentity identity,
  List<PrecheckResult> prechecks,
) async {
  _log('MODE', 'dry-run');
  _log(
    'DRY-RUN',
    'Would call signUp with display_name metadata: ${identity.displayName}',
  );
  _log('DRY-RUN', 'Would verify public.profiles row exists after signUp');
  _log('DRY-RUN', 'Would verify profile display_name matches metadata');
  _log('DRY-RUN', 'Would cleanup smoke auth user and profile');

  if (!serviceRolePresent(prechecks)) {
    _log(
      'PRECHECK',
      'SUPABASE_SERVICE_ROLE_KEY: missing — cleanup will be skipped',
    );
  } else {
    _log(
      'DRY-RUN',
      'Cleanup plan: DELETE from auth.users + DELETE from public.profiles',
    );
  }

  return exitPass;
}

// =============================================================================
// Parse arguments
// =============================================================================
(RunMode, String?) parseArgs(List<String> args) {
  RunMode mode = RunMode.dryRun;
  String? error;

  for (final arg in args) {
    switch (arg) {
      case '--dry-run':
        if (mode == RunMode.execute) {
          error = 'Cannot combine --dry-run and --execute';
        } else {
          mode = RunMode.dryRun;
        }
        break;
      case '--execute':
        if (mode == RunMode.dryRun && args.contains('--dry-run')) {
          error = 'Cannot combine --dry-run and --execute';
        } else {
          mode = RunMode.execute;
        }
        break;
      default:
        if (arg.startsWith('--')) {
          print('[WARN] Unknown flag: $arg — ignoring');
        }
    }
  }

  // Reject conflicting flags
  if (args.contains('--dry-run') && args.contains('--execute')) {
    return (RunMode.dryRun, 'Cannot combine --dry-run and --execute');
  }

  return (mode, error);
}

// =============================================================================
// Main
// =============================================================================
Future<int> main(List<String> args) async {
  // Parse mode
  final (mode, argError) = parseArgs(args);
  if (argError != null) {
    _log('ERROR', argError);
    return exitFailed;
  }

  _log('MODE', mode == RunMode.dryRun ? 'dry-run' : 'execute');

  // Load configuration from environment
  final config = SmokeConfig.fromEnvironment();

  // Generate smoke identity
  final identity = generateSmokeIdentity(
    emailPrefix: config.smokeEmailPrefix,
    emailDomain: config.testEmailDomain,
  );
  _log('IDENTITY', 'email=${identity.email}');
  _log('IDENTITY', 'display_name=${identity.displayName}');

  // Run prechecks
  final prechecks = runPrechecks(config, mode);

  // Validate required config
  if (!allRequiredEnvPresent(prechecks)) {
    _log('ERROR', 'Missing required environment variables');
    return exitMissingConfig;
  }

  // Mode-specific run
  if (mode == RunMode.dryRun) {
    final rc = await runDryRun(config, identity, prechecks);
    _logResult(rc == exitPass ? 'DRY_RUN_PASS' : 'DRY_RUN_FAIL');
    return rc;
  } else {
    // Execute mode: check service role requirement first
    if (!serviceRolePresent(prechecks)) {
      _log(
        'ERROR',
        'SUPABASE_SERVICE_ROLE_KEY is required for execute mode cleanup',
      );
      return exitMissingConfig;
    }
    try {
      final rc = await runExecute(config, identity);
      _logResult('EXECUTE_PASS');
      return rc;
    } on UnimplementedError catch (e) {
      _log('ERROR', e.message);
      _logResult('EXECUTE_NOT_IMPLEMENTED');
      return exitExecuteNotImplemented;
    } catch (e) {
      _log('ERROR', 'Unexpected error: $e');
      return exitFailed;
    }
  }
}
